00083 static void img2buf_normal (imgpel** imgX, unsigned char* buf, int size_x, int size_y, int symbol_size_in_bytes, int crop_left, int crop_right, int crop_top, int crop_bottom, int iOutStride)
00084 {
00085   int i,j;
00086 
00087   int twidth  = size_x - crop_left - crop_right;
00088   int theight = size_y - crop_top - crop_bottom;
00089 
00090   int size = 0;
00091 
00092   // sizeof (imgpel) > sizeof(char)
00093   // little endian
00094   if (sizeof (imgpel) < symbol_size_in_bytes)
00095   {
00096     // this should not happen. we should not have smaller imgpel than our source material.
00097     size = sizeof (imgpel);
00098     // clear buffer
00099     for(j=0; j<theight; j++)
00100       memset (buf+j*iOutStride, 0, (twidth * symbol_size_in_bytes));
00101   }
00102   else
00103   {
00104     size = symbol_size_in_bytes;
00105   }
00106 
00107   if ((crop_top || crop_bottom || crop_left || crop_right) || (size != 1))
00108   {
00109     for(i=crop_top; i<size_y-crop_bottom; i++)
00110     {
00111       int ipos = (i - crop_top) * iOutStride;
00112       for(j=crop_left; j<size_x-crop_right; j++)
00113       {
00114         memcpy(buf+(ipos+(j-crop_left)*symbol_size_in_bytes),&(imgX[i][j]), size);
00115       }
00116     }
00117   }
00118   else
00119   {
00120 #if (IMGTYPE == 0)
00121     //if (sizeof(imgpel) == sizeof(char))
00122     {
00123       //memcpy(buf, &(imgX[0][0]), size_y * size_x * sizeof(imgpel));
00124       for(j=0; j<size_y; j++)
00125         memcpy(buf+j*iOutStride, imgX[j], size_x*sizeof(imgpel));
00126     }
00127     //else
00128 #else
00129     {
00130       imgpel *cur_pixel;
00131       unsigned char *pDst;
00132       for(j = 0; j < size_y; j++)
00133       {
00134         cur_pixel = imgX[j];
00135         pDst = buf +j*iOutStride;
00136         for(i=0; i < size_x; i++)
00137           *(pDst++)=(unsigned char)*(cur_pixel++);
00138       }
00139     }
00140 #endif
00141   }
00142 }
