00168 static void img2buf_byte (imgpel** imgX, unsigned char* buf, int size_x, int size_y, int symbol_size_in_bytes, int crop_left, int crop_right, int crop_top, int crop_bottom, int iOutStride)
00169 {
00170   int twidth  = size_x - crop_left - crop_right;
00171   int theight = size_y - crop_top - crop_bottom;
00172   imgpel **img = &imgX[crop_top];
00173   int i;
00174   for(i = 0; i < theight; i++) 
00175   {
00176     memcpy(buf, *img++ + crop_left, twidth);
00177     buf += iOutStride;
00178   }
00179 }
