00205 static void img2buf_endian (imgpel** imgX, unsigned char* buf, int size_x, int size_y, int symbol_size_in_bytes, int crop_left, int crop_right, int crop_top, int crop_bottom, int iOutStride)
00206 {
00207   int i,j;
00208   unsigned char  ui8;
00209   uint16 tmp16, ui16;
00210   unsigned long  tmp32, ui32;
00211 
00212   //int twidth  = size_x - crop_left - crop_right;
00213 
00214   // big endian
00215   switch (symbol_size_in_bytes)
00216   {
00217   case 1:
00218     {
00219       for(i=crop_top;i<size_y-crop_bottom;i++)
00220       {
00221         for(j=crop_left;j<size_x-crop_right;j++)
00222         {
00223           ui8 = (unsigned char) (imgX[i][j]);
00224           buf[(j-crop_left+((i-crop_top)*iOutStride))] = ui8;
00225         }
00226       }
00227       break;
00228     }
00229   case 2:
00230     {
00231       for(i=crop_top;i<size_y-crop_bottom;i++)
00232       {
00233         for(j=crop_left;j<size_x-crop_right;j++)
00234         {
00235           tmp16 = (uint16) (imgX[i][j]);
00236           ui16  = (uint16) ((tmp16 >> 8) | ((tmp16&0xFF)<<8));
00237           memcpy(buf+((j-crop_left+((i-crop_top)*iOutStride))*2),&(ui16), 2);
00238         }
00239       }
00240       break;
00241     }
00242   case 4:
00243     {
00244       for(i=crop_top;i<size_y-crop_bottom;i++)
00245       {
00246         for(j=crop_left;j<size_x-crop_right;j++)
00247         {
00248           tmp32 = (unsigned long) (imgX[i][j]);
00249           ui32  = (unsigned long) (((tmp32&0xFF00)<<8) | ((tmp32&0xFF)<<24) | ((tmp32&0xFF0000)>>8) | ((tmp32&0xFF000000)>>24));
00250           memcpy(buf+((j-crop_left+((i-crop_top)*iOutStride))*4),&(ui32), 4);
00251         }
00252       }
00253       break;
00254     }
00255   default:
00256     {
00257       error ("writing only to formats of 8, 16 or 32 bit allowed on big endian architecture", 500);
00258       break;
00259     }
00260   }
00261 }
