00276 void flush_pending_output(VideoParameters *p_Vid, int p_out)
00277 {
00278   if (p_Vid->pending_output_state != FRAME)
00279   {
00280     write_out_picture(p_Vid, p_Vid->pending_output, p_out);
00281   }
00282 
00283   if (p_Vid->pending_output->imgY)
00284   {
00285     free_mem2Dpel (p_Vid->pending_output->imgY);
00286     p_Vid->pending_output->imgY=NULL;
00287   }
00288   if (p_Vid->pending_output->imgUV)
00289   {
00290     free_mem3Dpel (p_Vid->pending_output->imgUV);
00291     p_Vid->pending_output->imgUV=NULL;
00292   }
00293 
00294   p_Vid->pending_output_state = FRAME;
00295 }
