00310 void write_picture(VideoParameters *p_Vid, StorablePicture *p, int p_out, int real_structure)
00311 {
00312    int i, add;
00313 
00314   if (real_structure==FRAME)
00315   {
00316     
00317     flush_pending_output(p_Vid, p_out);
00318     write_out_picture(p_Vid, p, p_out);
00319     return;
00320   }
00321   if (real_structure == p_Vid->pending_output_state)
00322   {
00323     flush_pending_output(p_Vid, p_out);
00324     write_picture(p_Vid, p, p_out, real_structure);
00325     return;
00326   }
00327 
00328   if (p_Vid->pending_output_state == FRAME)
00329   {
00330     p_Vid->pending_output->size_x = p->size_x;
00331     p_Vid->pending_output->size_y = p->size_y;
00332     p_Vid->pending_output->size_x_cr = p->size_x_cr;
00333     p_Vid->pending_output->size_y_cr = p->size_y_cr;
00334     p_Vid->pending_output->chroma_format_idc = p->chroma_format_idc;
00335 
00336     p_Vid->pending_output->frame_mbs_only_flag = p->frame_mbs_only_flag;
00337     p_Vid->pending_output->frame_cropping_flag = p->frame_cropping_flag;
00338     if (p_Vid->pending_output->frame_cropping_flag)
00339     {
00340       p_Vid->pending_output->frame_crop_left_offset = p->frame_crop_left_offset;
00341       p_Vid->pending_output->frame_crop_right_offset = p->frame_crop_right_offset;
00342       p_Vid->pending_output->frame_crop_top_offset = p->frame_crop_top_offset;
00343       p_Vid->pending_output->frame_crop_bottom_offset = p->frame_crop_bottom_offset;
00344     }
00345 
00346     get_mem2Dpel (&(p_Vid->pending_output->imgY), p_Vid->pending_output->size_y, p_Vid->pending_output->size_x);
00347     get_mem3Dpel (&(p_Vid->pending_output->imgUV), 2, p_Vid->pending_output->size_y_cr, p_Vid->pending_output->size_x_cr);
00348 
00349     clear_picture(p_Vid, p_Vid->pending_output);
00350 
00351     // copy first field
00352     if (real_structure == TOP_FIELD)
00353     {
00354       add = 0;
00355     }
00356     else
00357     {
00358       add = 1;
00359     }
00360 
00361     for (i=0; i<p_Vid->pending_output->size_y; i+=2)
00362     {
00363       memcpy(p_Vid->pending_output->imgY[(i+add)], p->imgY[(i+add)], p->size_x * sizeof(imgpel));
00364     }
00365     for (i=0; i<p_Vid->pending_output->size_y_cr; i+=2)
00366     {
00367       memcpy(p_Vid->pending_output->imgUV[0][(i+add)], p->imgUV[0][(i+add)], p->size_x_cr * sizeof(imgpel));
00368       memcpy(p_Vid->pending_output->imgUV[1][(i+add)], p->imgUV[1][(i+add)], p->size_x_cr * sizeof(imgpel));
00369     }
00370     p_Vid->pending_output_state = real_structure;
00371   }
00372   else
00373   {
00374     if (  (p_Vid->pending_output->size_x!=p->size_x) || (p_Vid->pending_output->size_y!= p->size_y)
00375        || (p_Vid->pending_output->frame_mbs_only_flag != p->frame_mbs_only_flag)
00376        || (p_Vid->pending_output->frame_cropping_flag != p->frame_cropping_flag)
00377        || ( p_Vid->pending_output->frame_cropping_flag &&
00378             (  (p_Vid->pending_output->frame_crop_left_offset   != p->frame_crop_left_offset)
00379              ||(p_Vid->pending_output->frame_crop_right_offset  != p->frame_crop_right_offset)
00380              ||(p_Vid->pending_output->frame_crop_top_offset    != p->frame_crop_top_offset)
00381              ||(p_Vid->pending_output->frame_crop_bottom_offset != p->frame_crop_bottom_offset)
00382             )
00383           )
00384        )
00385     {
00386       flush_pending_output(p_Vid, p_out);
00387       write_picture (p_Vid, p, p_out, real_structure);
00388       return;
00389     }
00390     // copy second field
00391     if (real_structure == TOP_FIELD)
00392     {
00393       add = 0;
00394     }
00395     else
00396     {
00397       add = 1;
00398     }
00399 
00400     for (i=0; i<p_Vid->pending_output->size_y; i+=2)
00401     {
00402       memcpy(p_Vid->pending_output->imgY[(i+add)], p->imgY[(i+add)], p->size_x * sizeof(imgpel));
00403     }
00404     for (i=0; i<p_Vid->pending_output->size_y_cr; i+=2)
00405     {
00406       memcpy(p_Vid->pending_output->imgUV[0][(i+add)], p->imgUV[0][(i+add)], p->size_x_cr * sizeof(imgpel));
00407       memcpy(p_Vid->pending_output->imgUV[1][(i+add)], p->imgUV[1][(i+add)], p->size_x_cr * sizeof(imgpel));
00408     }
00409 
00410     flush_pending_output(p_Vid, p_out);
00411   }
00412 }
