00439 static void allocate_p_dec_pic(VideoParameters *p_Vid, DecodedPicList *pDecPic, StorablePicture *p, int iLumaSize, int iFrameSize, int iLumaSizeX, int iLumaSizeY, int iChromaSizeX, int iChromaSizeY)
00440 {
00441   int symbol_size_in_bytes = ((p_Vid->pic_unit_bitsize_on_disk+7) >> 3);
00442   
00443   if(pDecPic->pY)
00444     mem_free(pDecPic->pY);
00445   pDecPic->iBufSize = iFrameSize;
00446   pDecPic->pY = mem_malloc(pDecPic->iBufSize);
00447   pDecPic->pU = pDecPic->pY+iLumaSize;
00448   pDecPic->pV = pDecPic->pU + ((iFrameSize-iLumaSize)>>1);
00449   //init;
00450   pDecPic->iYUVFormat = p->chroma_format_idc;
00451   pDecPic->iYUVStorageFormat = 0;
00452   pDecPic->iBitDepth = p_Vid->pic_unit_bitsize_on_disk;
00453   pDecPic->iWidth = iLumaSizeX; //p->size_x;
00454   pDecPic->iHeight = iLumaSizeY; //p->size_y;
00455   pDecPic->iYBufStride = iLumaSizeX*symbol_size_in_bytes; //p->size_x *symbol_size_in_bytes;
00456   pDecPic->iUVBufStride = iChromaSizeX*symbol_size_in_bytes; //p->size_x_cr*symbol_size_in_bytes;
00457 }
