00472 static void write_out_picture(VideoParameters *p_Vid, StorablePicture *p, int p_out)
00473 {
00474   InputParameters *p_Inp = p_Vid->p_Inp;
00475   DecodedPicList *pDecPic;
00476 
00477   static const int SubWidthC  [4]= { 1, 2, 2, 1};
00478   static const int SubHeightC [4]= { 1, 2, 1, 1};
00479 
00480   int crop_left, crop_right, crop_top, crop_bottom;
00481   int symbol_size_in_bytes = ((p_Vid->pic_unit_bitsize_on_disk+7) >> 3);
00482   int rgb_output =  p_Vid->p_EncodePar[p->layer_id]->rgb_output; //(p_Vid->active_sps->vui_seq_parameters.matrix_coefficients==0);
00483   unsigned char *buf;
00484   //int iPicSizeTab[4] = {2, 3, 4, 6};
00485   int iLumaSize, iFrameSize;
00486   int iLumaSizeX, iLumaSizeY;
00487   int iChromaSizeX, iChromaSizeY;
00488 
00489   int ret;
00490 
00491   if (p->non_existing)
00492     return;
00493 
00494 #if (ENABLE_OUTPUT_TONEMAPPING)
00495   // note: this tone-mapping is working for RGB format only. Sharp
00496   if (p->seiHasTone_mapping && rgb_output)
00497   {
00498     //printf("output frame %d with tone model id %d\n",  p->frame_num, p->tone_mapping_model_id);
00499     symbol_size_in_bytes = (p->tonemapped_bit_depth>8)? 2 : 1;
00500     tone_map(p->imgY, p->tone_mapping_lut, p->size_x, p->size_y);
00501     tone_map(p->imgUV[0], p->tone_mapping_lut, p->size_x_cr, p->size_y_cr);
00502     tone_map(p->imgUV[1], p->tone_mapping_lut, p->size_x_cr, p->size_y_cr);
00503   }
00504 #endif
00505 
00506   // should this be done only once?
00507   if (p->frame_cropping_flag)
00508   {
00509     crop_left   = SubWidthC [p->chroma_format_idc] * p->frame_crop_left_offset;
00510     crop_right  = SubWidthC [p->chroma_format_idc] * p->frame_crop_right_offset;
00511     crop_top    = SubHeightC[p->chroma_format_idc] * ( 2 - p->frame_mbs_only_flag ) * p->frame_crop_top_offset;
00512     crop_bottom = SubHeightC[p->chroma_format_idc] * ( 2 - p->frame_mbs_only_flag ) * p->frame_crop_bottom_offset;
00513   }
00514   else
00515   {
00516     crop_left = crop_right = crop_top = crop_bottom = 0;
00517   }
00518   iChromaSizeX =  p->size_x_cr- p->frame_crop_left_offset -p->frame_crop_right_offset;
00519   iChromaSizeY = p->size_y_cr - ( 2 - p->frame_mbs_only_flag ) * p->frame_crop_top_offset -( 2 - p->frame_mbs_only_flag ) * p->frame_crop_bottom_offset;
00520   iLumaSizeX = p->size_x - crop_left-crop_right;
00521   iLumaSizeY = p->size_y - crop_top - crop_bottom;
00522   iLumaSize  = iLumaSizeX * iLumaSizeY * symbol_size_in_bytes;
00523   iFrameSize = (iLumaSizeX * iLumaSizeY + 2 * (iChromaSizeX * iChromaSizeY)) * symbol_size_in_bytes; //iLumaSize*iPicSizeTab[p->chroma_format_idc]/2;
00524 
00525   //printf ("write frame size: %dx%d\n", p->size_x-crop_left-crop_right,p->size_y-crop_top-crop_bottom );
00526 
00527 #if 0 // Build the decoded picture in memeory for LCEVC
00528   // We need to further cleanup this function
00529   if (p_out == -1)
00530     return;
00531 #endif
00532 
00533   // KS: this buffer should actually be allocated only once, but this is still much faster than the previous version
00534   pDecPic = get_one_avail_dec_pic_from_list(p_Vid->pDecOuputPic, 0, 0);
00535   if( (pDecPic->pY == NULL)
00536     || (pDecPic->iBufSize < iFrameSize)
00537     )
00538     allocate_p_dec_pic(p_Vid, pDecPic, p, iLumaSize, iFrameSize, iLumaSizeX, iLumaSizeY, iChromaSizeX, iChromaSizeY);
00539 #if (MVC_EXTENSION_ENABLE)
00540   {
00541     pDecPic->bValid = 1;
00542     pDecPic->iViewId = p->view_id >=0 ? p->view_id : -1;
00543   }
00544 #else
00545   pDecPic->bValid = 1;
00546 #endif
00547   
00548   pDecPic->iPOC = p->frame_poc;
00549   
00550   if (NULL==pDecPic->pY)
00551   {
00552     no_mem_exit("write_out_picture: buf");
00553   }
00554 
00555   
00556   if(rgb_output)
00557   {
00558     buf = malloc (p->size_x * p->size_y * symbol_size_in_bytes);
00559     crop_left   = p->frame_crop_left_offset;
00560     crop_right  = p->frame_crop_right_offset;
00561     crop_top    = ( 2 - p->frame_mbs_only_flag ) * p->frame_crop_top_offset;
00562     crop_bottom = ( 2 - p->frame_mbs_only_flag ) * p->frame_crop_bottom_offset;
00563 
00564     p_Vid->img2buf (p->imgUV[1], buf, p->size_x_cr, p->size_y_cr, symbol_size_in_bytes, crop_left, crop_right, crop_top, crop_bottom, pDecPic->iYBufStride);
00565     if (p_out >= 0)
00566     {
00567       ret = write(p_out, buf, (p->size_y_cr-crop_bottom-crop_top)*(p->size_x_cr-crop_right-crop_left)*symbol_size_in_bytes);
00568       if (ret != ((p->size_y_cr-crop_bottom-crop_top)*(p->size_x_cr-crop_right-crop_left)*symbol_size_in_bytes))
00569       {
00570         error ("write_out_picture: error writing to RGB file", 500);
00571       }
00572     }
00573 
00574     if (p->frame_cropping_flag)
00575     {
00576       crop_left   = SubWidthC[p->chroma_format_idc] * p->frame_crop_left_offset;
00577       crop_right  = SubWidthC[p->chroma_format_idc] * p->frame_crop_right_offset;
00578       crop_top    = SubHeightC[p->chroma_format_idc]*( 2 - p->frame_mbs_only_flag ) * p->frame_crop_top_offset;
00579       crop_bottom = SubHeightC[p->chroma_format_idc]*( 2 - p->frame_mbs_only_flag ) * p->frame_crop_bottom_offset;
00580     }
00581     else
00582     {
00583       crop_left = crop_right = crop_top = crop_bottom = 0;
00584     }
00585     if(buf) 
00586       free(buf);
00587   }
00588 
00589   buf = (pDecPic->bValid==1)? pDecPic->pY: pDecPic->pY+iLumaSizeX*symbol_size_in_bytes;
00590 
00591   p_Vid->img2buf (p->imgY, buf, p->size_x, p->size_y, symbol_size_in_bytes, crop_left, crop_right, crop_top, crop_bottom, pDecPic->iYBufStride);
00592   if(p_out >=0)
00593   {
00594     ret = write(p_out, buf, (p->size_y-crop_bottom-crop_top)*(p->size_x-crop_right-crop_left)*symbol_size_in_bytes);
00595     if (ret != ((p->size_y-crop_bottom-crop_top)*(p->size_x-crop_right-crop_left)*symbol_size_in_bytes))
00596     {
00597       error ("write_out_picture: error writing to YUV file", 500);
00598     }
00599   }
00600 
00601   if (p->chroma_format_idc!=YUV400)
00602   {
00603     crop_left   = p->frame_crop_left_offset;
00604     crop_right  = p->frame_crop_right_offset;
00605     crop_top    = ( 2 - p->frame_mbs_only_flag ) * p->frame_crop_top_offset;
00606     crop_bottom = ( 2 - p->frame_mbs_only_flag ) * p->frame_crop_bottom_offset;
00607     buf = (pDecPic->bValid==1)? pDecPic->pU : pDecPic->pU + iChromaSizeX*symbol_size_in_bytes;
00608     p_Vid->img2buf (p->imgUV[0], buf, p->size_x_cr, p->size_y_cr, symbol_size_in_bytes, crop_left, crop_right, crop_top, crop_bottom, pDecPic->iUVBufStride);
00609     if(p_out >= 0)
00610     {
00611       ret = write(p_out, buf, (p->size_y_cr-crop_bottom-crop_top)*(p->size_x_cr-crop_right-crop_left)* symbol_size_in_bytes);
00612       if (ret != ((p->size_y_cr-crop_bottom-crop_top)*(p->size_x_cr-crop_right-crop_left)* symbol_size_in_bytes))
00613       {
00614         error ("write_out_picture: error writing to YUV file", 500);
00615       }
00616     }
00617 
00618     if (!rgb_output)
00619     {
00620       buf = (pDecPic->bValid==1)? pDecPic->pV : pDecPic->pV + iChromaSizeX*symbol_size_in_bytes;
00621       p_Vid->img2buf (p->imgUV[1], buf, p->size_x_cr, p->size_y_cr, symbol_size_in_bytes, crop_left, crop_right, crop_top, crop_bottom, pDecPic->iUVBufStride);
00622 
00623       if(p_out >= 0)
00624       {
00625         ret = write(p_out, buf, (p->size_y_cr-crop_bottom-crop_top)*(p->size_x_cr-crop_right-crop_left)*symbol_size_in_bytes);
00626         if (ret != ((p->size_y_cr-crop_bottom-crop_top)*(p->size_x_cr-crop_right-crop_left)*symbol_size_in_bytes))
00627         {
00628           error ("write_out_picture: error writing to YUV file", 500);
00629         }
00630       }
00631     }
00632   }
00633   else
00634   {
00635     if (p_Inp->write_uv)
00636     {
00637       int i,j;
00638       imgpel cr_val = (imgpel) (1<<(p_Vid->bitdepth_luma - 1));
00639 
00640       get_mem3Dpel (&(p->imgUV), 1, p->size_y/2, p->size_x/2);
00641 
00642       for (j=0; j<p->size_y/2; j++)
00643       {
00644         for (i=0; i<p->size_x/2; i++)
00645         {
00646           p->imgUV[0][j][i]=cr_val;
00647         }
00648       }
00649 
00650       // fake out U=V=128 to make a YUV 4:2:0 stream
00651       buf = malloc (p->size_x*p->size_y*symbol_size_in_bytes);
00652       p_Vid->img2buf (p->imgUV[0], buf, p->size_x/2, p->size_y/2, symbol_size_in_bytes, crop_left/2, crop_right/2, crop_top/2, crop_bottom/2, pDecPic->iYBufStride/2);
00653 
00654       ret = write(p_out, buf, symbol_size_in_bytes * (p->size_y-crop_bottom-crop_top)/2 * (p->size_x-crop_right-crop_left)/2 );
00655       if (ret != (symbol_size_in_bytes * (p->size_y-crop_bottom-crop_top)/2 * (p->size_x-crop_right-crop_left)/2))
00656       {
00657         error ("write_out_picture: error writing to YUV file", 500);
00658       }
00659       ret = write(p_out, buf, symbol_size_in_bytes * (p->size_y-crop_bottom-crop_top)/2 * (p->size_x-crop_right-crop_left)/2 );
00660       if (ret != (symbol_size_in_bytes * (p->size_y-crop_bottom-crop_top)/2 * (p->size_x-crop_right-crop_left)/2))
00661       {
00662         error ("write_out_picture: error writing to YUV file", 500);
00663       }
00664       free(buf);
00665       free_mem3Dpel(p->imgUV);
00666       p->imgUV=NULL;
00667     }
00668   }
00669 
00670   //free(buf);
00671  if(p_out >=0)
00672    pDecPic->bValid = 0;
00673 
00674   //  fsync(p_out);
00675 }
