00683 void init_out_buffer(VideoParameters *p_Vid)
00684 {
00685   p_Vid->out_buffer = alloc_frame_store();
00686 
00687 #if (PAIR_FIELDS_IN_OUTPUT)
00688   p_Vid->pending_output = calloc (sizeof(StorablePicture), 1);
00689   if (NULL==p_Vid->pending_output) no_mem_exit("init_out_buffer");
00690   p_Vid->pending_output->imgUV = NULL;
00691   p_Vid->pending_output->imgY  = NULL;
00692 #endif
00693 }
