00701 void uninit_out_buffer(VideoParameters *p_Vid)
00702 {
00703   free_frame_store(p_Vid->out_buffer);
00704   p_Vid->out_buffer=NULL;
00705 #if (PAIR_FIELDS_IN_OUTPUT)
00706   flush_pending_output(p_Vid, p_Vid->p_out);
00707   free (p_Vid->pending_output);
