00717 void clear_picture(VideoParameters *p_Vid, StorablePicture *p)
00718 {
00719   int i,j;
00720 
00721   for(i=0;i<p->size_y;i++)
00722   {
00723     for (j=0; j<p->size_x; j++)
00724       p->imgY[i][j] = (imgpel) p_Vid->dc_pred_value_comp[0];
00725   }
00726   for(i=0;i<p->size_y_cr;i++)
00727   {
00728     for (j=0; j<p->size_x_cr; j++)
00729       p->imgUV[0][i][j] = (imgpel) p_Vid->dc_pred_value_comp[1];
00730   }
00731   for(i=0;i<p->size_y_cr;i++)
00732   {
00733     for (j=0; j<p->size_x_cr; j++)
00734       p->imgUV[1][i][j] = (imgpel) p_Vid->dc_pred_value_comp[2];
00735   }
00736 }
