00752 void write_unpaired_field(VideoParameters *p_Vid, FrameStore* fs, int p_out)
00753 {
00754   StorablePicture *p;
00755   assert (fs->is_used<3);
00756 
00757   if(fs->is_used & 0x01)
00758   {
00759     // we have a top field
00760     // construct an empty bottom field
00761     p = fs->top_field;
00762     fs->bottom_field = alloc_storable_picture(p_Vid, BOTTOM_FIELD, p->size_x, 2*p->size_y, p->size_x_cr, 2*p->size_y_cr, 1);
00763     fs->bottom_field->chroma_format_idc = p->chroma_format_idc;
00764     clear_picture(p_Vid, fs->bottom_field);
00765     dpb_combine_field_yuv(p_Vid, fs);
00766 #if (MVC_EXTENSION_ENABLE)
00767     fs->frame->view_id = fs->view_id;
00768 #endif
00769     write_picture (p_Vid, fs->frame, p_out, TOP_FIELD);
00770   }
00771 
00772   if(fs->is_used & 0x02)
00773   {
00774     // we have a bottom field
00775     // construct an empty top field
00776     p = fs->bottom_field;
00777     fs->top_field = alloc_storable_picture(p_Vid, TOP_FIELD, p->size_x, 2*p->size_y, p->size_x_cr, 2*p->size_y_cr, 1);
00778     fs->top_field->chroma_format_idc = p->chroma_format_idc;
00779     clear_picture(p_Vid, fs->top_field);
00780     fs ->top_field->frame_cropping_flag = fs->bottom_field->frame_cropping_flag;
00781     if(fs ->top_field->frame_cropping_flag)
00782     {
00783       fs ->top_field->frame_crop_top_offset = fs->bottom_field->frame_crop_top_offset;
00784       fs ->top_field->frame_crop_bottom_offset = fs->bottom_field->frame_crop_bottom_offset;
00785       fs ->top_field->frame_crop_left_offset = fs->bottom_field->frame_crop_left_offset;
00786       fs ->top_field->frame_crop_right_offset = fs->bottom_field->frame_crop_right_offset;
00787     }
00788     dpb_combine_field_yuv(p_Vid, fs);
00789 #if (MVC_EXTENSION_ENABLE)
00790     fs->frame->view_id = fs->view_id;
00791 #endif
00792     write_picture (p_Vid, fs->frame, p_out, BOTTOM_FIELD);
00793   }
00794 
00795   fs->is_used = 3;
00796 }
00797 
00809 void flush_direct_output(VideoParameters *p_Vid, int p_out)
00810 {
00811   write_unpaired_field(p_Vid, p_Vid->out_buffer, p_out);
00812 
00813   free_storable_picture(p_Vid->out_buffer->frame);
00814   p_Vid->out_buffer->frame = NULL;
00815   free_storable_picture(p_Vid->out_buffer->top_field);
00816   p_Vid->out_buffer->top_field = NULL;
00817   free_storable_picture(p_Vid->out_buffer->bottom_field);
00818   p_Vid->out_buffer->bottom_field = NULL;
00819   p_Vid->out_buffer->is_used = 0;
00820 }
00821 
00822 
00836 void write_stored_frame( VideoParameters *p_Vid, FrameStore *fs, int p_out)
00837 {
00838   // make sure no direct output field is pending
00839   flush_direct_output(p_Vid, p_out);
00840 
00841   if (fs->is_used<3)
00842   {
00843     write_unpaired_field(p_Vid, fs, p_out);
00844   }
00845   else
00846   {
00847     if (fs->recovery_frame)
00848       p_Vid->recovery_flag = 1;
00849     if ((!p_Vid->non_conforming_stream) || p_Vid->recovery_flag)
00850       write_picture(p_Vid, fs->frame, p_out, FRAME);
00851   }
00852 
00853   fs->is_output = 1;
00854 }
00855 
00870 void direct_output(VideoParameters *p_Vid, StorablePicture *p, int p_out)
00871 {
00872   InputParameters *p_Inp = p_Vid->p_Inp;
00873   if (p->structure==FRAME)
00874   {
00875     // we have a frame (or complementary field pair)
00876     // so output it directly
00877     flush_direct_output(p_Vid, p_out);
00878     write_picture (p_Vid, p, p_out, FRAME);
00879     calculate_frame_no(p_Vid, p);
00880     if (-1 != p_Vid->p_ref && !p_Inp->silent)
00881       find_snr(p_Vid, p, &p_Vid->p_ref);
00882     free_storable_picture(p);
00883     return;
00884   }
00885 
00886   if (p->structure == TOP_FIELD)
00887   {
00888     if (p_Vid->out_buffer->is_used &1)
00889       flush_direct_output(p_Vid, p_out);
00890     p_Vid->out_buffer->top_field = p;
00891     p_Vid->out_buffer->is_used |= 1;
00892   }
00893 
00894   if (p->structure == BOTTOM_FIELD)
00895   {
00896     if (p_Vid->out_buffer->is_used &2)
00897       flush_direct_output(p_Vid, p_out);
00898     p_Vid->out_buffer->bottom_field = p;
00899     p_Vid->out_buffer->is_used |= 2;
00900   }
00901 
00902   if (p_Vid->out_buffer->is_used == 3)
00903   {
00904     // we have both fields, so output them
00905     dpb_combine_field_yuv(p_Vid, p_Vid->out_buffer);
00906 #if (MVC_EXTENSION_ENABLE)
00907     p_Vid->out_buffer->frame->view_id = p_Vid->out_buffer->view_id;
00908 #endif
00909     write_picture (p_Vid, p_Vid->out_buffer->frame, p_out, FRAME);
00910 
00911     calculate_frame_no(p_Vid, p);
00912     if (-1 != p_Vid->p_ref && !p_Inp->silent)
00913       find_snr(p_Vid, p_Vid->out_buffer->frame, &p_Vid->p_ref);
00914     free_storable_picture(p_Vid->out_buffer->frame);
00915     p_Vid->out_buffer->frame = NULL;
00916     free_storable_picture(p_Vid->out_buffer->top_field);
00917     p_Vid->out_buffer->top_field = NULL;
00918     free_storable_picture(p_Vid->out_buffer->bottom_field);
00919     p_Vid->out_buffer->bottom_field = NULL;
00920     p_Vid->out_buffer->is_used = 0;
00921   }
00922 }
